-- sheet as it was started, which stands for any date before its first change). A change that left
-- the sheet as it was records nothing.
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL,
    taken_on DATE,
    data     VARBINARY NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, id);
-- Each SNAPSHOT line written for a person when the sheet's today changes: the day being left and their
-- due-total on it (null: n/a), kept in the order written (seq).
CREATE TABLE person_snapshot (
    person_id BIGINT NOT NULL REFERENCES person (id),
    seq       INT NOT NULL,
    on_date   DATE NOT NULL,
    due_total DECIMAL(14, 2),
    PRIMARY KEY (person_id, seq)
);

